SINA_SMART["anat2-lymph-nerves"] = {"lecture":"anat2-lymph-nerves","title":"Lymphatics and innervation of the abdomen","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"anat2-lymph-nerves:e0","text":"Lymph: fluid balance, immune surveillance, fat absorption.","topic":"The lymphatic system","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-lymph-nerves:e1","text":"Thoracic duct → left subclavian vein.","topic":"The lymphatic system","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-lymph-nerves:e2","text":"Parietal lymph follows veins; visceral lymph follows arteries.","topic":"Parietal and visceral drainage","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-lymph-nerves:e3","text":"Foregut → coeliac; midgut → SMA; hindgut → IMA nodes.","topic":"Parietal and visceral drainage","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-lymph-nerves:e4","text":"Cisterna chyli: L1-L2, 5-7 cm → thoracic duct at T12.","topic":"Parietal and visceral drainage","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-lymph-nerves:e5","text":"Oesophagus: longitudinal submucosal lymphatics; upper → cervical, middle → mediastinal, lower → coeliac.","topic":"Parietal and visceral drainage","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-lymph-nerves:e6","text":"Wall nerves: thoracoabdominal T7-T11, subcostal T12, iliohypogastric and ilio-inguinal L1, genitofemoral L1-L2.","topic":"Somatic innervation","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-lymph-nerves:e7","text":"Greater splanchnic T5-T9 → coeliac; lesser T10-T11 → SM; least T12 → aorticorenal; lumbar L1-L2 → IM.","topic":"Autonomic and enteric innervation","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-lymph-nerves:e8","text":"Vagus: to 2/3 transverse colon; pelvic splanchnics S2-S4: hindgut and pelvis.","topic":"Autonomic and enteric innervation","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"anat2-lymph-nerves:e9","text":"ENS: myenteric (Auerbach) and submucosal (Meissner) plexuses.","topic":"Autonomic and enteric innervation","sec":3,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"1ng88ag":"a","1pqqm8e":"a","cw00a9":"a","1fd58yp":"a","ggqn18":"a","r7jj85":"a","1gpnkvb":"a","1t2g37g":"a","5b17en":"a","mx8xw0":"a","122h2da":"a","qpmjwe":"a","o4t67p":"a"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"anat2-lymph-nerves:e0":{"s":0,"u":["Lymph: fluid balance, immune surveillance, fat absorption.","Functions: fluid balance (returns interstitial fluid), immune surveillance (filters pathogens and cancer cells), fat absorption (chylomicrons via lacteals to the thoracic duct).","A network of vessels and nodes carrying lymph (fluid with immune cells, proteins and fats) alongside the circulation."],"dp":[]},"anat2-lymph-nerves:e1":{"s":0,"u":["Thoracic duct → left subclavian vein.","Lymph flows centrally and ends in the thoracic duct , which empties into the left subclavian vein ."],"dp":[{"h":"Clinical","t":"Lymphatic injury in surgery → chylous ascites (milky fluid). Gastric cancer can spread up the thoracic duct to the left supraclavicular node (Virchow's, Troisier's sign) ."}]},"anat2-lymph-nerves:e2":{"s":1,"u":["Parietal lymph follows veins; visceral lymph follows arteries.","Visceral lymphatics drain the organs and follow the arteries to the pre-aortic nodes : foregut → coeliac , midgut → superior mesenteric , hindgut → inferior mesenteric nodes.","Parietal lymphatics drain the wall and follow the veins : superficially, above the umbilicus to axillary and below it to superficial inguinal nodes; deeply to external iliac, common iliac and lumbar (para-aortic) nodes."],"dp":[{"h":"Note","t":"Visceral lymph follows the arteries (foregut → coeliac, midgut → SMA, hindgut → IMA nodes); parietal lymph follows the veins ."},{"h":"Clinical","t":"Referred visceral pain follows the sympathetic level: foregut → epigastrium , midgut → umbilicus , hindgut → suprapubic region."}]},"anat2-lymph-nerves:e3":{"s":1,"u":["Foregut → coeliac; midgut → SMA; hindgut → IMA nodes.","Visceral lymphatics drain the organs and follow the arteries to the pre-aortic nodes : foregut → coeliac , midgut → superior mesenteric , hindgut → inferior mesenteric nodes.","Organs: oesophagus (longitudinal submucosal network allowing spread up and down): upper third → deep cervical, middle → mediastinal, lower → left gastric and coeliac nodes; liver : parenchymal and subperitoneal systems, mainly to abdominal and mediastinal nodes; biliary tree : cystic → hepatic → coeliac and pyloric → peripancreatic nodes."],"dp":[]},"anat2-lymph-nerves:e4":{"s":1,"u":["Cisterna chyli: L1-L2, 5-7 cm → thoracic duct at T12.","The lumbar trunks converge in front of L1-L2 into the cisterna chyli (a fusiform sac about 5-7 cm long), which continues, right of the aorta, as the thoracic duct at about T12."],"dp":[{"h":"Note","t":"Cisterna chyli at L1-L2 → thoracic duct (through the aortic hiatus, T12) → left subclavian/internal jugular junction ."}]},"anat2-lymph-nerves:e5":{"s":1,"u":["Oesophagus: longitudinal submucosal lymphatics; upper → cervical, middle → mediastinal, lower → coeliac.","Organs: oesophagus (longitudinal submucosal network allowing spread up and down): upper third → deep cervical, middle → mediastinal, lower → left gastric and coeliac nodes; liver : parenchymal and subperitoneal systems, mainly to abdominal and mediastinal nodes; biliary tree : cystic → hepatic → coeliac and pyloric → peripancreatic nodes."],"dp":[]},"anat2-lymph-nerves:e6":{"s":2,"u":["Wall nerves: thoracoabdominal T7-T11, subcostal T12, iliohypogastric and ilio-inguinal L1, genitofemoral L1-L2.","Thoracoabdominal nerves (T7-T11) , continuations of the lower intercostals: skin and muscles of the anterolateral wall; subcostal nerve (T12) ; iliohypogastric (L1) : suprapubic skin, internal oblique and transversus; ilio-inguinal (L1) : passes through the inguinal canal; upper medial thigh, mons pubis, scrotum or labia majora; genitofemoral (L1-L2) : genital branch to the cremaster and scrotal/labial skin, femoral branch to the upper anterior thigh."],"dp":[{"h":"Note","t":"Wall nerves: T7-T11 thoracoabdominal, T12 subcostal, L1 iliohypogastric and ilio-inguinal (the latter through the inguinal canal), L1-L2 genitofemoral (cremaster: genital branch)."},{"h":"Clinical","t":"Cremasteric reflex (stroke the inner thigh → testis rises): afferent femoral branch, efferent genital branch of genitofemoral (L1-L2)."}]},"anat2-lymph-nerves:e7":{"s":3,"u":["Greater splanchnic T5-T9 → coeliac; lesser T10-T11 → SM; least T12 → aorticorenal; lumbar L1-L2 → IM.","Sympathetic (preganglionic neurons T5-L2): greater splanchnic (T5-T9) → coeliac ganglion , lesser (T10-T11) → superior mesenteric ganglion , least (T12) → aorticorenal ganglion , lumbar splanchnics (L1-L2) → inferior mesenteric ganglion and hypogastric plexuses; effects: inhibits peristalsis, contracts sphincters, vasoconstriction."],"dp":[{"h":"Note","t":"Splanchnic nerves : greater ( T5-T9 ) → coeliac; lesser ( T10-T11 ) → superior mesenteric; least ( T12 ) → aorticorenal; lumbar (L1-L2) → inferior mesenteric."}]},"anat2-lymph-nerves:e8":{"s":3,"u":["Vagus: to 2/3 transverse colon; pelvic splanchnics S2-S4: hindgut and pelvis.","Parasympathetic : vagus to the foregut and midgut up to the proximal two thirds of the transverse colon; pelvic splanchnic nerves (S2-S4) to the hindgut, bladder and reproductive organs; synapse in intramural ganglia; effects: stimulates peristalsis and secretion, relaxes sphincters, enables urination, defecation and sexual function."],"dp":[{"h":"Note","t":"Parasympathetic : vagus as far as the distal third of the transverse colon (midgut/hindgut boundary); beyond it pelvic splanchnics S2-S4 ."}]},"anat2-lymph-nerves:e9":{"s":3,"u":["ENS: myenteric (Auerbach) and submucosal (Meissner) plexuses.","The enteric nervous system ('second brain') has the myenteric (Auerbach) plexus between the muscle layers (motility) and the submucosal (Meissner) plexus (secretion, local blood flow)."],"dp":[]}},"meta":{"1ng88ag":{"a":"recall","vg":"anat2-lymph-nerves:e1/recall/1"},"1pqqm8e":{"a":"recall","vg":"anat2-lymph-nerves:e2/recall/1"},"cw00a9":{"a":"recall","vg":"anat2-lymph-nerves:e2/recall/2"},"1fd58yp":{"a":"recall","vg":"anat2-lymph-nerves:e4/recall/1"},"ggqn18":{"a":"recall","vg":"anat2-lymph-nerves:e3/recall/1"},"r7jj85":{"a":"relationship","vg":"anat2-lymph-nerves:e5/relationship/1"},"1gpnkvb":{"a":"recall","vg":"anat2-lymph-nerves:e6/recall/1"},"1t2g37g":{"a":"recall","vg":"anat2-lymph-nerves:e6/recall/2"},"5b17en":{"a":"recall","vg":"anat2-lymph-nerves:e7/recall/1"},"mx8xw0":{"a":"recall","vg":"anat2-lymph-nerves:e8/recall/1"},"122h2da":{"a":"recall","vg":"anat2-lymph-nerves:e8/recall/2"},"qpmjwe":{"a":"recall","vg":"anat2-lymph-nerves:e7/recall/2"},"o4t67p":{"a":"recall","vg":"anat2-lymph-nerves:e9/recall/1"}},"explRev":"9caee15e4014"};
